// TH15 v1.00b Extra, Boss7 non-spell (type: nonspell).
// Source: st07bs.ecl.txt:951-1026; dependencies Boss7_at / Boss7_at2 /
// BossItemPhase3; entry state from st07bs.ecl.txt:8-39.
//
// Source timeline (script clock of Boss7, timerReset at line 969):
//   entry t=0 (card 121 after the 120-frame opening and the 1-frame task birth)
//   +2://2 and +2://4 chapter/stat gates (omitted, delays kept)
//   timerReset t=4  -> source window [t=4, t=4204] = card [125, 4325]
//   setInterrupt timeout 4200, hp floor 3000 -> phase_begin below
//   wait(120), +20://24 gate, wait(30) -> attack loop starts at t=174
// The phase clock starts at card 1 (spawn task first run); TIME_LIMIT 4324
// nominally ends at card 4325, the source 4200-frame timeout.  The harness
// reports PHASE_ENDED at card 4327 (settle-phase resolution, 2 frames tail).

const TIME_LIMIT: int = 4324;
const OPENING_BUFFER: int = 120;

// TH15 type 9 (KUNAI), color 13. Bullet catalog: TH15_* aliases.
const TH15_KUNAI: int = 496;
const BULLET_COLOR: int = 13;

// Boss7_at / Boss7_at2 emit 25 ways, 4 layers through etAim(0,10).
// The layer angles are alpha +/- H(4,q) with H = delta/2, delta/2, 3delta/2,
// 3delta/2 (aim-modes mode10).  All layers use speed 2 because each etOn is
// preceded by etSpeed(0,2,2); the initial etSpeed(0,2,3) is overwritten.
// delta values are BAM-converted at the two decimal places of the source:
//   0.022689281 rad = 236.66 BAM -> half 118, three-half 355
//   0.010471975 rad = 109.23 BAM -> half  55, three-half 164
//   0.017453292 rad = 182.04 BAM -> half  91, three-half 273
// Boss7_at also advances alpha by +3deg*F0 in the first 10 waves and
// -1deg*F0 in the last 10; Boss7_at2 uses +3deg*F0 and -1deg*F0.

// 24px etDist and the birth ANIM's -4*velocity displacement give the net
// spawn distance 24 - 4*2 = 16px (all four layers are speed 2).
xformdef VELTIME_60_TO_6 {
    step_speed(6fx, 60 + 65536 * EASE_LINEAR);
}

// Configure s0 once per Boss7_at call (source etNew(0) + etSprite/etAim/
// etCount/etSpeed/etEx/etDist).
sub boss7_configure_at() {
    sh_reset(0);
    sh_sprite(0, TH15_KUNAI, BULLET_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 25, 1);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, 16fx);
    // The zero-arg xform program lives in the frame that references it; attach
    // it in boss7_fire_wave (same frame as sh_fire), not in this helper.
}

// One source wave: layer q=0..3 in source order.
sub boss7_fire_wave(base: int, half: int, three_half: int) {
    sh_xform(0, VELTIME_60_TO_6);
    sh_angle(0, (base + half) as angle, 0deg);
    sh_fire(0);
    sh_angle(0, (base - half) as angle, 0deg);
    sh_fire(0);
    sh_angle(0, (base + three_half) as angle, 0deg);
    sh_fire(0);
    sh_angle(0, (base - three_half) as angle, 0deg);
    sh_fire(0);
}

// st07bs.ecl.txt:1028-1062.  F0 comes from the caller.
sub boss7_at(f0: fx) {
    boss7_configure_at();
    var a: int = rand(65536) - 32768;      // %RANDRAD: -pi..pi in BAM
    var sa: int = (546.1333588fx * f0) as int; // 3deg * F0
    var sb: int = (182.0444390fx * f0) as int; // 1deg * F0
    for i in 0..10 {
        boss7_fire_wave(a, 118, 355);
        a = a + sa;
        wait(5);
    }
    for j in 0..10 {
        boss7_fire_wave(a, 118, 355);
        a = a - sb;
        wait(5);
    }
}

// st07bs.ecl.txt:1064-1098.  Layer deltas change between the two loops.
sub boss7_at2(f0: fx) {
    boss7_configure_at();
    var a: int = rand(65536) - 32768;
    var sa: int = (546.1333588fx * f0) as int; // 3deg * F0
    var sb: int = (182.0444390fx * f0) as int; // 1deg * F0
    for i in 0..10 {
        boss7_fire_wave(a, 55, 164);           // delta 0.6deg
        a = a + sa;
        wait(5);
    }
    for j in 0..10 {
        boss7_fire_wave(a, 91, 273);           // delta 1deg
        a = a - sb;
        wait(5);
    }
}

// 412 moveRand(60, 4, 1.9), shared recipe for an ABS-only, REL=0, no-mirror
// enemy.  Direction selection uses the current position and player x; the
// speed decreases linearly from 1.9 to 0 over 60 ticks.  The per-frame limit
// box of Boss() is moveLimit(0,128,280,64): x in [-140,140], y in [96,160].
// Inner direction thresholds are x +/- width/4 = +/-70 and y 112..144.
// Target phase 5 integrates after ECL, so each helper tick sets the clamped
// displacement for the next movement update; the final tick zeroes speed.
sub boss7_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32767 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // no normalization here: source applies fabs tests to this value
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // +/-pi/2 guard, 0.05 rad ~= 522 BAM
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    var ca: fx = cos(a as angle);
    var sa: fx = sin(a as angle);
    for k in 1..61 {
        var v: fx = 1.9fx - (k as fx) * 1.9fx / 60fx;
        var nx: fx = $self_x + ca * v;
        var ny: fx = $self_y + sa * v;
        if nx < -140fx { nx = -140fx; }
        if nx > 140fx { nx = 140fx; }
        if ny < 96fx { ny = 96fx; }
        if ny > 160fx { ny = 160fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
}

async sub boss7_main() {
    // Common Boss state: box is st07bs.ecl.txt:31-32 (setHurtbox 40,
    // setHitbox 48; target radii are half of the source circle values).
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    if global(GVAR_RANK) != RANK_EXTRA {
        loop { wait(60); }
    }

    // Non-spell phase: source setInterrupt(0,3000,4200,"BossCard7") and
    // timerReset at line 969.  hp floor 3000; invulnerable so only timeout.
    phase_begin(0, none, TIME_LIMIT, 3000);

    wait(OPENING_BUFFER);

    // st07bs.ecl.txt:953-962.  lifeSet(20000) is the spawn HP; TIMEOUT==0.
    wait(4); // source +2://2 +2://4 (chapter/stat/flag/drop omitted)

    // Line 969 timerReset, then killAllAsync/enmKillAll/etCancel(640) and
    // the spellEnd/funcSet(0)/laserCancel/move resets.  The card owns one
    // enemy and starts with an empty field, so the clears have no object.
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR); // moveVel/moveVelTime(0,...)
    // movePosTime(0,...) only cancels the position interpolation.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT); // line 993, already at (0,128)
    wait(120);                              // line 994
    wait(20);                               // +20://24 time gate
    wait(30);                               // line 1004

    // Boss7_1272 loop: four 20-wave calls per 640-frame cycle; each call is
    // 100 frames of firing (20 waves x wait(5)) plus a 60-frame moveRand wait.
    loop {
        boss7_at(1fx);
        boss7_move_rand();
        boss7_at(-1fx);
        boss7_move_rand();
        boss7_at2(2.718255fx);
        boss7_move_rand();
        boss7_at2(-2.718255fx);
        boss7_move_rand();
    }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 20000, 0, 0, 0, boss7_main);
    loop { wait(600); }
}
